function r(n,t="COP"){return n==null||!Number.isFinite(n)?"—":new Intl.NumberFormat("es-CO",{style:"currency",currency:t,maximumFractionDigits:0}).format(n)}function u(n){if(n==null||!Number.isFinite(n))return"—";const t=Math.abs(n),e=n<0?"-":"";return t>=1e9?`${e}$ ${(t/1e9).toFixed(1)} mm`:t>=1e6?`${e}$ ${(t/1e6).toFixed(1)} M`:t>=1e3?`${e}$ ${(t/1e3).toFixed(0)} k`:`${e}$ ${t.toFixed(0)}`}function m(n,t=0){return n==null||!Number.isFinite(n)?"—":new Intl.NumberFormat("es-CO",{minimumFractionDigits:t,maximumFractionDigits:t}).format(n)}function s(n,t=1){return n==null||!Number.isFinite(n)?"—":`${n.toFixed(t)} %`}function c(n,t=1,e=""){return`${n>0?"+":""}${n.toFixed(t)}${e}`}function o(n,t=60){return n?n.length>t?`${n.slice(0,t-1)}…`:n:""}function a(n){const t=new Date(n);return Number.isNaN(t.getTime())?n:new Intl.DateTimeFormat("es-CO",{dateStyle:"short",timeStyle:"short"}).format(t)}export{u as a,c,a as f,r as m,m as n,s as p,o as t};
